def cycle_sort(array: list[int]) -> list[int]:
    length = len(array)
    for start in range(length - 1):
        item = array[start]
        position = start
        for i in range(start + 1, length):
            if array[i] < item:
                position += 1
        if position == start:
            continue
        while item == array[position]:
            position += 1
        array[position], item = (item, array[position])
        while position != start:
            position = start
            for i in range(start + 1, length):
                if array[i] < item:
                    position += 1
            while item == array[position]:
                position += 1
            array[position], item = (item, array[position])
    return array

def min_max(arr):
    if not arr:
        return (None, None)
    length = len(arr)
    if length % 2 == 0:
        max_elem = max(arr[0], arr[1])
        min_elem = min(arr[0], arr[1])
        start = 2
    else:
        max_elem = min_elem = arr[0]
        start = 1
    for i in range(start, length, 2):
        if arr[i] < arr[i + 1]:
            max_elem = max(max_elem, arr[i + 1])
            min_elem = min(min_elem, arr[i])
            continue
        max_elem = max(max_elem, arr[i])
        min_elem = min(min_elem, arr[i + 1])
    return (min_elem, max_elem)

def merge_intervals(intervals):
    n = len(intervals)
    if n == 0:
        return []
    intervals.sort(key=lambda interval: interval[0])
    mergedIntervals = []
    mergedIntervals.append(intervals[0])
    for i in range(1, n):
        if intervals[i][0] <= mergedIntervals[-1][1] + 1:
            mergedIntervals[-1] = (mergedIntervals[-1][0], max(mergedIntervals[-1][1], intervals[i][1]))
        else:
            mergedIntervals.append(intervals[i])
    return mergedIntervals
